window.kbPageData["views/entry/k-57553598a9256d6d"] = {"key":"entry/k-57553598a9256d6d","state":{"route":"entry/k-57553598a9256d6d"},"node":{"id":"k-57553598a9256d6d","mode":"k","title":"食品安全民事公益诉讼的惩罚性赔偿","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["食品安全民事公益诉讼中检察机关请求惩罚性赔偿的权限及销售额基数"],"qs":["江苏 2024 B类 行测#18"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"已核实考前存在以涉案食品销售价款计算惩罚性赔偿的典型案例。仍需核对有无同期依据支持仅凭题述无证生产、产地冒充及销售规模即满足本案的公益损害和惩罚性赔偿条件。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","review":{"definition":"原题引文：检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","explanation":"本题选A。考前已有检察公益诉讼典型案例以不符合食品安全标准的食品销售价款计赔。题中千万元销售额表明涉案饮用水销售规模，本身无法证明食品安全问题或公益损害。无证生产和冒充进口应结合产品安全标准、潜在风险及受影响的消费者范围判断。题解援引的消费者个人欺诈三倍赔偿，与公益诉讼采用何种计赔基数是两个问题。","references":[{"source":"web-ab539ec6d5a4da7a","location":"沙坡头区生产、销售不符合安全标准食品案，一审判决结果","quote":"食品价款十倍的惩罚性赔偿金"}],"evidence":"检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 行测#18":{"paper":"江苏 2024 B类 行测","n":18,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",7],"card":"5672449a128edb1da00efc80","links":[{"id":"k-57553598a9256d6d","role":"直接考查","why":"参考答案将检察机关的赔偿请求权限与销售额计赔基数列为同一判断。"}]}},"terms":{},"references":{"web-ab539ec6d5a4da7a":{"name":"宁夏检察机关发布的食品药品安全公益诉讼典型案例","url":"https://nx.jcy.gov.cn/QJCY/njjcxw/njajjj/202303/t20230315_700513.html"}},"topics":[],"units":{"k-57553598a9256d6d":[["江苏 2024 B类 行测#18"]]}};
